contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        address ownerBefore = c.owner();
        uint cBalBefore = address(c).balance;
        uint ownerBalBefore = ownerBefore.balance;

        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }

        if (reverted) {
            assert(address(c).balance == cBalBefore);
        } else {
            assert(address(c).balance == 0);
            assert(ownerBefore.balance == ownerBalBefore + cBalBefore + amount);
        }
    }

    receive() external payable {}
}

